#include <iostream>
#include <memory>

class Resource {
public:
    Resource() { std::cout << "Resource acquired" << std::endl; }
    ~Resource() { std::cout << "Resource destroyed" << std::endl; }
    void sayHello() { std::cout << "Hello from Resource" << std::endl; }
};

int main() {
    {
        auto ptr = std::make_unique<Resource>();
        ptr->sayHello();
    } // unique_ptr automatically deletes Resource here

    std::shared_ptr<Resource> sharedPtr1 = std::make_shared<Resource>();
    {
        auto sharedPtr2 = sharedPtr1; // shared ownership
        sharedPtr2->sayHello();
    } // Resource is destroyed when last shared_ptr goes out of scope
    return 0;
}
